"use client";

import { loadFont as loadSans } from "@remotion/google-fonts/InstrumentSans";
import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import type React from "react";
import { AbsoluteFill, Easing, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";
import {
  type ResolvedElement,
  type Timing,
  useTimeline,
} from "@/lib/remocn/timeline";
import {
  type CalendarBookingElementId,
  calendarBookingTimeline,
} from "./timeline";

const sans = loadSans("normal", { weights: ["400"], subsets: ["latin"] });
const serif = loadSerif("normal", { weights: ["400"], subsets: ["latin"] });

export interface BookingHost {
  name: string;
  email?: string;
  /** Two-letter monogram for the avatar. */
  initials?: string;
}

export interface BookingEvent {
  title: string;
  description?: string;
  durations?: string[];
  /** Index into `durations` that is booked. */
  duration?: number;
  location?: string;
  timezone?: string;
  /** Month shown on the calendar. */
  month?: string;
  year?: number;
  /** Weekday of the 1st, 0 = Sunday. */
  firstWeekday?: number;
  daysInMonth?: number;
  /** First bookable day; weekends are never bookable. */
  firstAvailable?: number;
}

export interface CalendarBookingProps {
  host?: BookingHost;
  event?: BookingEvent;
  slots?: string[];
  /** Slot the cursor picks. Defaults to "10:30am" or the 4th slot. */
  pick?: string;
  /** Day of the month the cursor picks. */
  day?: number;
  /** Label of the button the picked slot splits into. */
  confirmLabel?: string;
  /** Line next to the check once the booking lands. */
  sentLabel?: string;
  /** Headline of the confirmation, before the host's first name. */
  bookedLabel?: string;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  /** Solid fill in place of the gradient ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Instrument Sans by default. */
  fontFamily?: string;
  /** Size of the card, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "light" | "dark";
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  /**
   * Moves, trims or stretches the card, the push-in, the cursor's clicks
   * and the success view, by the ids in `./timeline`. Frames on the scene
   * timeline, after `delay` and `speed`.
   */
  timing?: Timing<CalendarBookingElementId>;
}

const DEFAULT_HOST: BookingHost = {
  name: "Maya Chen",
  email: "maya@kitebase.io",
  initials: "MC",
};

const DEFAULT_EVENT: BookingEvent = {
  title: "Product walkthrough",
  description:
    "Thirty minutes on the registry, live previews and the render pipeline. Bring the product you want to launch.",
  durations: ["15m", "30m", "45m"],
  duration: 1,
  location: "Video call",
  timezone: "Europe/Lisbon",
  month: "June",
  year: 2026,
  firstWeekday: 1,
  daysInMonth: 30,
  firstAvailable: 9,
};

const DEFAULT_SLOTS = [
  "9:00am",
  "9:30am",
  "10:00am",
  "10:30am",
  "11:00am",
  "1:30pm",
  "2:00pm",
  "3:30pm",
];

const WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const WEEKDAY_LONG = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
];

const SPR = {
  heavy: { mass: 1, damping: 26, stiffness: 120 },
  card: { mass: 0.8, damping: 18, stiffness: 160 },
  chip: { mass: 0.5, damping: 12, stiffness: 200 },
  morph: { damping: 200 },
};
const EASE = {
  enter: Easing.bezier(0.32, 0.72, 0, 1),
  soft: Easing.bezier(0.22, 1, 0.36, 1),
  move: Easing.bezier(0.65, 0, 0.35, 1),
  exit: Easing.bezier(0.55, 0, 1, 0.45),
  camera: Easing.bezier(0.87, 0, 0.13, 1),
};
const CL = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const clamp01 = (v: number) => Math.min(1, Math.max(0, v));
const tween = (
  f: number,
  from: number,
  len: number,
  easing: (t: number) => number,
) => interpolate(f, [from, from + len], [0, 1], { ...CL, easing });

const PALETTES = {
  light: {
    card: "#FFFFFF",
    text: "#18181B",
    muted: "#71717A",
    faint: "#B4B4BB",
    line: "rgba(24,24,27,0.08)",
    tint: "rgba(24,24,27,0.045)",
    ink: "#18181B",
    inkText: "#FFFFFF",
    shadow:
      "0 0 0 1px rgba(24,24,27,0.06), 0 2px 4px rgba(24,24,27,0.04), 0 36px 80px -24px rgba(20,24,60,0.32)",
    ghost: "0 0 0 1px rgba(24,24,27,0.1), 0 1px 2px rgba(24,24,27,0.05)",
  },
  dark: {
    card: "#141518",
    text: "#EDEDEF",
    muted: "#8E9097",
    faint: "#4E5057",
    line: "rgba(255,255,255,0.07)",
    tint: "rgba(255,255,255,0.05)",
    ink: "#EDEDEF",
    inkText: "#141518",
    shadow:
      "0 0 0 1px rgba(255,255,255,0.09), inset 0 1px 0 rgba(255,255,255,0.06), 0 40px 90px -24px rgba(0,0,0,0.75)",
    ghost: "0 0 0 1px rgba(255,255,255,0.1)",
  },
};
type Palette = (typeof PALETTES)["light"];

const LIGHT_GROUND: Partial<GradientParams> = {
  colors: ["#a9bcff", "#3b5bfd", "#22349e", "#c9d6ff"],
  background: "#f1f1ef",
};

function withAlpha(color: string, alpha: number) {
  const hex = color.replace("#", "");
  const full = hex.length === 3 ? hex.replace(/(.)/g, "$1$1") : hex;
  if (!/^[0-9a-fA-F]{6}$/.test(full)) return color;
  const n = Number.parseInt(full, 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${alpha})`;
}

type IconName = "clock" | "video" | "globe" | "left" | "right" | "check";

function Icon({
  name,
  color,
  size = 18,
}: {
  name: IconName;
  color: string;
  size?: number;
}) {
  const p = {
    fill: "none",
    stroke: color,
    strokeWidth: 1.5,
    strokeLinecap: "round" as const,
    strokeLinejoin: "round" as const,
  };
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      aria-hidden
      style={{ display: "block", flexShrink: 0 }}
    >
      {name === "clock" && (
        <>
          <circle cx={12} cy={12} r={8.5} {...p} />
          <path d="M12 7.5V12l3 2" {...p} />
        </>
      )}
      {name === "video" && (
        <>
          <rect x={3} y={6.5} width={12.5} height={11} rx={2.5} {...p} />
          <path d="M15.5 10.5l5-3v9l-5-3" {...p} />
        </>
      )}
      {name === "globe" && (
        <>
          <circle cx={12} cy={12} r={8.5} {...p} />
          <path
            d="M3.5 12h17M12 3.5c2.8 3 2.8 14 0 17M12 3.5c-2.8 3-2.8 14 0 17"
            {...p}
          />
        </>
      )}
      {name === "left" && <path d="M14.5 6.5L9 12l5.5 5.5" {...p} />}
      {name === "right" && <path d="M9.5 6.5L15 12l-5.5 5.5" {...p} />}
      {name === "check" && <path d="M6 12.5l4 4 8-9" {...p} />}
    </svg>
  );
}

/** A spring's leftover under a thousandth of a pixel counts as arrived. */
const near = (v: number) => (Math.abs(v) < 1e-3 ? 0 : v);
const shift = (dx: number, dy: number) =>
  near(dx) || near(dy) ? `translate(${near(dx)}px, ${near(dy)}px)` : "";

function Cursor({
  x,
  y,
  rest,
  press,
  opacity,
}: {
  x: number;
  y: number;
  rest: { x: number; y: number };
  press: number;
  opacity: number;
}) {
  // Laid out where the cursor comes to rest; the travel is a transform so its
  // box edges don't step pixel by pixel.
  const dx = near(x - rest.x);
  const dy = near(y - rest.y);
  return (
    <svg
      width={24}
      height={28}
      viewBox="0 0 20 24"
      aria-hidden
      style={{
        position: "absolute",
        left: rest.x - 2.2,
        top: rest.y - 2.2,
        opacity,
        transformOrigin: "2px 2px",
        transform: `${dx || dy ? `translate(${dx}px, ${dy}px) ` : ""}scale(${1 - 0.04 * press})`,
        filter: "drop-shadow(0 2px 3px rgba(0,0,0,0.3))",
        overflow: "visible",
      }}
    >
      <path
        d="M2 2 L2 19.5 L6.6 15.4 L9.8 22.4 L12.9 21 L9.8 14.2 L16 14.2 Z"
        fill="#FFFFFF"
        stroke="#111114"
        strokeWidth={1.2}
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function geometry(tall: boolean, gridRows: number) {
  if (tall) {
    const cell = 64;
    const gap = 8;
    const hostH = 206;
    const calY = hostH + 24;
    const gridY = calY + 84;
    const gridBottom = gridY + gridRows * (cell + gap);
    const slotY = gridBottom + 18;
    return {
      cell,
      gap,
      host: { x: 0, y: 0, w: 560, h: hostH },
      calX: 28,
      calY,
      weekY: calY + 50,
      gridY,
      slotHeadY: slotY,
      slotX: 28,
      slotY: slotY + 44,
      slotCols: 2,
      slotW: 246,
      slotH: 46,
      slotStep: 54,
      narrow: { w: 560, h: slotY },
      wide: { w: 560, h: slotY + 44 + 4 * 54 + 16 },
      done: { w: 560, h: 440 },
    };
  }
  const cell = 56;
  const gap = 6;
  const hostW = 300;
  const calX = hostW + 32;
  const gridW = 7 * cell + 6 * gap;
  const narrowW = calX + gridW + 32;
  return {
    cell,
    gap,
    host: { x: 0, y: 0, w: hostW, h: 488 },
    calX,
    calY: 30,
    weekY: 86,
    gridY: 122,
    slotHeadY: 30,
    slotX: narrowW + 24,
    slotY: 86,
    slotCols: 1,
    slotW: 212,
    slotH: 42,
    slotStep: 50,
    narrow: { w: narrowW, h: 488 },
    wide: { w: narrowW + 260, h: 488 },
    done: { w: 620, h: 424 },
  };
}

export function CalendarBooking(props: CalendarBookingProps) {
  const {
    host = DEFAULT_HOST,
    event: eventProp,
    slots = DEFAULT_SLOTS,
    pick,
    day = 18,
    confirmLabel = "Confirm",
    sentLabel = "Invite sent to your inbox",
    bookedLabel = "You’re booked with",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sans.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "light",
    ground,
    groundParams,
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    calendarBookingTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const cardEl = tl.get("card");
  const cameraEl = tl.get("camera");
  const cursorEl = tl.get("cursor");
  const dayEl = tl.get("day");
  const slotEl = tl.get("slot");
  const confirmEl = tl.get("confirm");
  const successEl = tl.get("success");
  const tall = height > width;
  const SW = tall ? 600 : 1280;
  const SH = tall ? (600 * height) / width : 720;
  const k = width / SW;
  const dark = theme === "dark";
  const c = { ...PALETTES[theme], text: ink ?? PALETTES[theme].text };
  const event = { ...DEFAULT_EVENT, ...eventProp };
  const first = event.firstWeekday ?? 1;
  const days = event.daysInMonth ?? 30;
  const gridRows = Math.ceil((first + days) / 7);
  const G = geometry(tall, gridRows);
  const spAt = (f: number, at: number, config: Record<string, number>) =>
    spring({ frame: f - at, fps, config });
  const sp = (at: number, config: Record<string, number>) =>
    spAt(frame, at, config);
  // Whether a value built from the frame moves into or out of this frame.
  const stirs = (at: (f: number) => number, eps: number) =>
    Math.abs(at(frame + 1) - at(frame)) > eps ||
    Math.abs(at(frame) - at(frame - 1)) > eps;
  const isOpen = (d: number) => {
    const wd = (first + d - 1) % 7;
    return d >= (event.firstAvailable ?? 1) && wd !== 0 && wd !== 6;
  };
  const shown = slots.slice(0, tall ? 8 : 7);
  const wanted = shown.indexOf(pick ?? "10:30am");
  const pickIdx = wanted >= 0 ? wanted : Math.min(3, shown.length - 1);
  const pickLabel = shown[pickIdx] ?? "";

  const widenAt = dayEl.start + dayEl.beat("widenAt");
  const morphAt = confirmEl.start + confirmEl.beat("morphAt");
  const cardOp = tween(frame, cardEl.start, cardEl.length, EASE.enter);
  const dayFill = sp(dayEl.start, SPR.chip);
  const widen = sp(widenAt, SPR.heavy);
  const split = sp(slotEl.start + slotEl.beat("splitAt"), SPR.card);
  const morph = sp(morphAt, SPR.morph);
  const camAt = (f: number) =>
    1 +
    0.03 * tween(f, cameraEl.start, cameraEl.length, EASE.camera) +
    0.015 *
      tween(
        f,
        confirmEl.start + confirmEl.beat("pushAt"),
        confirmEl.beat("push"),
        EASE.camera,
      );
  const cam = camAt(frame);
  // The camera carries the whole scene, so its tilt covers everything under
  // it; the movers below tilt themselves only while it holds still.
  const camMoving = stirs(camAt, 1e-6);

  const bookW = G.narrow.w + (G.wide.w - G.narrow.w) * widen;
  const bookH = G.narrow.h + (G.wide.h - G.narrow.h) * widen;
  const cardW = bookW + (G.done.w - bookW) * morph;
  const cardH = bookH + (G.done.h - bookH) * morph;
  // The card is laid out at its final size and place; its recentring as it
  // widens and morphs, and its rise, are a transform, since layout rounds a
  // box and a baseline to whole pixels.
  const restX = (SW - G.done.w) / 2;
  const restY = (SH - G.done.h) / 2;
  const cardShiftAt = (f: number) => {
    const wi = spAt(f, widenAt, SPR.heavy);
    const mo = spAt(f, morphAt, SPR.morph);
    const bw = G.narrow.w + (G.wide.w - G.narrow.w) * wi;
    const bh = G.narrow.h + (G.wide.h - G.narrow.h) * wi;
    const cw = bw + (G.done.w - bw) * mo;
    const ch = bh + (G.done.h - bh) * mo;
    return {
      x: (G.done.w - cw) / 2,
      y: (G.done.h - ch) / 2 + (1 - spAt(f, cardEl.start, SPR.heavy)) * 36,
    };
  };
  const cardShift = cardShiftAt(frame);
  const cardMoving =
    !camMoving &&
    (stirs((f) => cardShiftAt(f).x, 5e-4) ||
      stirs((f) => cardShiftAt(f).y, 5e-4));
  /** How far a click's element has the button pressed, at frame `f`. */
  const pressAt = (f: number, e: ResolvedElement<CalendarBookingElementId>) =>
    clamp01(
      spAt(f, e.start + e.beat("pressIn"), SPR.chip) -
        spAt(f, e.start + e.beat("pressOut"), SPR.chip),
    );
  const confirmPressing =
    !camMoving && !cardMoving && stirs((f) => pressAt(f, confirmEl), 1e-5);

  const cellPos = (d: number) => {
    const idx = first + d - 1;
    return {
      x: G.calX + (idx % 7) * (G.cell + G.gap),
      y: G.gridY + Math.floor(idx / 7) * (G.cell + G.gap),
    };
  };
  const slotPos = (i: number) => ({
    x: G.slotX + (i % G.slotCols) * (G.slotW + 12),
    y: G.slotY + Math.floor(i / G.slotCols) * G.slotStep,
  });
  const narrowOrigin = { x: (SW - G.narrow.w) / 2, y: (SH - G.narrow.h) / 2 };
  const wideOrigin = { x: (SW - G.wide.w) / 2, y: (SH - G.wide.h) / 2 };
  const dc = cellPos(day);
  const dayPt = {
    x: narrowOrigin.x + dc.x + G.cell / 2 + 4,
    y: narrowOrigin.y + dc.y + G.cell / 2 + 4,
  };
  const ps = slotPos(pickIdx);
  const half = (G.slotW - 8) / 2;
  const slotPt = {
    x: wideOrigin.x + ps.x + G.slotW / 2 + 6,
    y: wideOrigin.y + ps.y + G.slotH / 2 + 4,
  };
  const confirmPt = {
    x: wideOrigin.x + ps.x + half + 8 + half / 2 + 4,
    y: slotPt.y,
  };
  const start = tall ? { x: 660, y: 1120 } : { x: 1360, y: 800 };
  const legs = [
    { at: cursorEl.start, from: start, to: dayPt, arc: 1 },
    {
      at: slotEl.start + slotEl.beat("legAt"),
      from: dayPt,
      to: slotPt,
      arc: -1,
    },
    {
      at: confirmEl.start + confirmEl.beat("legAt"),
      from: slotPt,
      to: confirmPt,
      arc: 1,
    },
    {
      at: confirmEl.start + confirmEl.beat("exitAt"),
      from: confirmPt,
      to: { x: confirmPt.x + 60, y: confirmPt.y + 110 },
      arc: -1,
    },
  ];
  let curX = start.x;
  let curY = start.y;
  for (const leg of legs) {
    const p = sp(leg.at, SPR.heavy);
    const dx = leg.to.x - leg.from.x;
    const dy = leg.to.y - leg.from.y;
    const len = Math.hypot(dx, dy) || 1;
    const bend = Math.sin(clamp01(p) * Math.PI) * Math.min(60, len * 0.14);
    curX += dx * p + (-dy / len) * bend * leg.arc;
    curY += dy * p + (dx / len) * bend * leg.arc;
  }
  const pressOf = (e: ResolvedElement<CalendarBookingElementId>) =>
    pressAt(frame, e);
  const press = Math.max(pressOf(dayEl), pressOf(slotEl), pressOf(confirmEl));
  const curOp =
    tween(frame, cursorEl.start, cursorEl.beat("fadeIn"), EASE.enter) *
    (1 -
      tween(
        frame,
        confirmEl.start + confirmEl.beat("fadeAt"),
        confirmEl.beat("fade"),
        EASE.exit,
      ));

  const bookOp =
    1 - tween(frame, morphAt, confirmEl.beat("bookOut"), EASE.exit);
  const doneOp = tween(
    frame,
    confirmEl.start + confirmEl.beat("doneAt"),
    confirmEl.beat("done"),
    EASE.enter,
  );
  const slotHover = tween(
    frame,
    slotEl.start + slotEl.beat("hoverAt"),
    slotEl.beat("hover"),
    EASE.enter,
  );
  const wd = (first + day - 1) % 7;
  const end = shown[pickIdx + 1] ?? "";

  return (
    <AbsoluteFill
      style={{
        overflow: "hidden",
        fontFamily,
        WebkitFontSmoothing: "antialiased",
      }}
    >
      {background === undefined ? (
        <GshGround
          preset={ground ?? (dark ? "film-blue" : "glasswork")}
          params={groundParams ?? (dark ? undefined : LIGHT_GROUND)}
          timeOffset={2}
          timeScale={0.45}
        />
      ) : (
        <AbsoluteFill
          style={{
            background: background === "transparent" ? undefined : background,
          }}
        />
      )}
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: SW,
            height: SH,
            transform: `scale(${k})`,
            transformOrigin: "0 0",
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              transform: `scale(${cam})${glide(camMoving)}`,
              transformOrigin: `${SW / 2}px ${SH / 2}px`,
            }}
          >
            <div
              style={{
                position: "absolute",
                left: restX,
                top: restY,
                width: cardW,
                height: cardH,
                transform:
                  shift(cardShift.x, cardShift.y) + glide(cardMoving) ||
                  undefined,
                borderRadius: 22,
                background: c.card,
                boxShadow: c.shadow,
                overflow: "hidden",
                opacity: cardOp,
              }}
            >
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  width: G.wide.w,
                  height: G.wide.h,
                  opacity: bookOp,
                  transform: `scale(${1 - 0.03 * morph})`,
                  transformOrigin: "50% 40%",
                }}
              >
                <HostPanel host={host} event={event} c={c} tall={tall} G={G} />
                <div
                  style={{
                    position: "absolute",
                    left: G.calX,
                    top: G.calY,
                    width: 7 * G.cell + 6 * G.gap,
                    height: 32,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                  }}
                >
                  <div style={{ fontSize: 19, color: c.text }}>
                    {event.month}{" "}
                    <span style={{ color: c.muted }}>{event.year}</span>
                  </div>
                  <div style={{ display: "flex", gap: 14 }}>
                    <Icon name="left" color={c.faint} size={20} />
                    <Icon name="right" color={c.text} size={20} />
                  </div>
                </div>
                {WEEKDAYS.map((w, i) => (
                  <div
                    key={w}
                    style={{
                      position: "absolute",
                      left: G.calX + i * (G.cell + G.gap),
                      top: G.weekY,
                      width: G.cell,
                      textAlign: "center",
                      fontSize: 16,
                      color: c.muted,
                    }}
                  >
                    {w}
                  </div>
                ))}
                {Array.from({ length: days }, (_, i) => i + 1).map((d) => {
                  const idx = first + d - 1;
                  const open = isOpen(d);
                  const sel = d === day;
                  const pos = cellPos(d);
                  const appear = tween(
                    frame,
                    cardEl.start +
                      cardEl.beat("gridAt") +
                      (idx % 7) * cardEl.beat("col") +
                      Math.floor(idx / 7) * cardEl.beat("row"),
                    cardEl.beat("cell"),
                    EASE.soft,
                  );
                  return (
                    <div
                      key={d}
                      style={{
                        position: "absolute",
                        left: pos.x,
                        top: pos.y,
                        width: G.cell,
                        height: G.cell,
                        borderRadius: 12,
                        background: open ? c.tint : "transparent",
                        opacity: appear,
                        transform: `translateY(${(1 - appear) * 8}px)`,
                      }}
                    >
                      {sel ? (
                        <div
                          style={{
                            position: "absolute",
                            inset: 0,
                            borderRadius: 12,
                            background: c.ink,
                            transform: `scale(${0.6 + 0.4 * dayFill})`,
                            opacity: clamp01(dayFill * 3),
                          }}
                        />
                      ) : null}
                      <div
                        style={{
                          position: "absolute",
                          inset: 0,
                          display: "flex",
                          alignItems: "center",
                          justifyContent: "center",
                          fontSize: 17,
                          fontVariantNumeric: "tabular-nums",
                          color:
                            sel && dayFill > 0.3
                              ? c.inkText
                              : open
                                ? c.text
                                : c.faint,
                        }}
                      >
                        {d}
                      </div>
                    </div>
                  );
                })}
                <div
                  style={{
                    position: "absolute",
                    left: tall ? 0 : G.narrow.w,
                    top: tall ? G.narrow.h - 1 : 0,
                    width: tall ? G.wide.w : 1,
                    height: tall ? 1 : G.wide.h,
                    background: c.line,
                    opacity: clamp01(widen * 2),
                  }}
                />
                <div
                  style={{
                    position: "absolute",
                    left: G.slotX,
                    top: G.slotHeadY,
                    height: 32,
                    display: "flex",
                    alignItems: "center",
                    fontSize: 19,
                    color: c.text,
                    opacity: tween(
                      frame,
                      dayEl.start + dayEl.beat("labelAt"),
                      dayEl.beat("label"),
                      EASE.enter,
                    ),
                  }}
                >
                  {WEEKDAY_LONG[wd].slice(0, 3)}&nbsp;
                  <span style={{ color: c.muted }}>{day}</span>
                </div>
                {shown.map((s, i) => {
                  const inn = sp(
                    dayEl.start +
                      dayEl.beat("slotsAt") +
                      i * dayEl.beat("slotStagger"),
                    SPR.card,
                  );
                  const picked = i === pickIdx;
                  const sv = picked ? split : 0;
                  const pos = slotPos(i);
                  const timeW = G.slotW - (G.slotW - half) * sv;
                  const base: React.CSSProperties = {
                    position: "absolute",
                    top: pos.y,
                    height: G.slotH,
                    borderRadius: 10,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    gap: 8,
                    fontSize: 17,
                    boxSizing: "border-box",
                    overflow: "hidden",
                    whiteSpace: "nowrap",
                    fontVariantNumeric: "tabular-nums",
                  };
                  return (
                    <div key={s}>
                      <div
                        style={{
                          ...base,
                          left: pos.x + (1 - inn) * 18,
                          width: timeW,
                          opacity: clamp01(inn * 1.5),
                          color: c.text,
                          background: picked && sv > 0.05 ? c.tint : c.card,
                          boxShadow:
                            picked && slotHover > 0 && sv < 0.5
                              ? `0 0 0 1px ${c.text}`
                              : c.ghost,
                        }}
                      >
                        {s}
                      </div>
                      {picked && sv > 0.01 ? (
                        <div
                          style={{
                            ...base,
                            left: pos.x + timeW + 8,
                            width: Math.max(0, G.slotW - timeW - 8),
                            background: accent,
                            color: "#FFFFFF",
                            opacity: clamp01(sv * 2),
                            boxShadow: "inset 0 1px 0 rgba(255,255,255,0.16)",
                            transform: `scale(${1 - 0.04 * pressOf(confirmEl)})${glide(confirmPressing)}`,
                          }}
                        >
                          {confirmLabel}
                        </div>
                      ) : null}
                    </div>
                  );
                })}
              </div>
              {morph > 0.01 ? (
                <SuccessView
                  frame={frame - successEl.start}
                  el={successEl}
                  fps={fps}
                  c={c}
                  accent={accent}
                  opacity={doneOp}
                  dx={(cardW - G.done.w) / 2}
                  dy={(cardH - G.done.h) / 2}
                  w={G.done.w}
                  h={G.done.h}
                  host={host}
                  event={event}
                  sentLabel={sentLabel}
                  bookedLabel={bookedLabel}
                  when={`${WEEKDAY_LONG[wd]}, ${event.month} ${day}`}
                  time={`${pickLabel}${end ? ` – ${end}` : ""}`}
                />
              ) : null}
            </div>
            <Cursor
              x={curX}
              y={curY}
              rest={legs[legs.length - 1].to}
              press={press}
              opacity={curOp}
            />
          </div>
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

